def compress_string(s: str) -> str:
    if not s:
        return ''
    res = []
    curr_char = s[0]
    count = 1
    for char in s[1:]:
        if char == curr_char:
            count += 1
        else:
            res.append(f'{curr_char}{count}')
            curr_char = char
            count = 1
    res.append(f'{curr_char}{count}')
    return ''.join(res)
